\section{Introduction}

\subsection{The reporting question}
Let a finite population be given and let $y$ be a numerical target attached to its
members. Suppose a base predictor $x$ has been fitted, explaining a share $R^2(x,y)$ of
the target's variance, and a second predictor $z$ is proposed. The decision turns on the
\emph{augmentation increment}
\[
  \Delta R^2 \;=\; R^2\big(\{x,z\},y\big) - R^2(x,y),
\]
the incremental share attributable to $z$ once $x$ is in the model. In applied
literature this is \emph{incremental validity}; in model selection it is the target of
an $F$-test for a nested model.

Decision makers rarely see raw moments. They see a dashboard: three variance shares
\[
  a = R^2(x,y), \qquad c = R^2(z,y), \qquad e = R^2(x,z),
\]
each a squared correlation, each in $[0,1]$, each blind to sign. Does the triple
determine $\Delta R^2$? We show it does not, quantify exactly how badly, and identify
the minimal repair.

\subsection{Why it fails}
A single-predictor variance share is genuinely sign-free. The augmentation increment is
not, because it is a \emph{comparison}: the partial-correlation identity
(Theorem~\ref{thm:pcorr}) gives
\[
  \Delta R^2 = \frac{(\rho_{zy} - \rho_{xy}\rho_{xz})^2}{1-\rho_{xz}^2},
\]
whose numerator subtracts the association the footprint already supplies from the
association the feature exhibits. Whether the terms cancel or reinforce is a matter of
sign, and it is exactly the signs that squaring destroys. The classical phenomenon of
\emph{suppression} is the applied face of this algebra.

\section{Setting and definitions}

\begin{definition}[Population]
A \emph{population} is a finite index set $I$ of \emph{keys} with weights
$p:I\to\R$, $p_i\ge0$, $\sum_i p_i = 1$. A \emph{feature} is any $f:I\to\R$.
\end{definition}

\begin{definition}[Weighted moments]
For features $f,g$ put
\[
  \ip{f}{g} = \sum_{i\in I} p_i f_i g_i,\quad \mu(f) = \ip{f}{\mathbf 1},\quad
  \cov(f,g) = \ip{f}{g}-\mu(f)\mu(g),\quad \var(f)=\cov(f,f).
\]
For features of positive variance,
\[
  R^2(f,g) = \frac{\cov(f,g)^2}{\var(f)\var(g)}, \qquad
  \rho_{fg} = \frac{\cov(f,g)}{\sqrt{\var(f)\var(g)}} .
\]
\end{definition}

\begin{proposition}[A reading is a squared correlation]\label{prop:sq}
$R^2(f,g) = \rho_{fg}^2$. Consequently populations whose correlations differ only by
signs present identical readings: the map from signed correlations to readings discards
exactly the sign bits.
\end{proposition}

\begin{definition}[Residual and partialled feature]
A feature $r$ is the \emph{residual of $y$ on $x$} if $y_i = a + bx_i + r_i$ for scalars
$a,b$ with $\ip{r}{\mathbf 1}=0$ and $\ip{x}{r}=0$; then
$b=\cov(x,y)/\var(x)$. A feature $\zt$ is \emph{$z$ partialled on $x$} if
$\ip{\zt}{\mathbf 1}=0$, $\ip{x}{\zt}=0$ and $z-\zt$ lies in the span of $\mathbf 1$ and
$x$; explicitly $\zt=(z-\mu(z))-\frac{\cov(x,z)}{\var(x)}(x-\mu(x))$, with
\emph{partialled energy}
\begin{equation}\label{eq:energy}
  \ip{\zt}{\zt} = \var(z)-\frac{\cov(x,z)^2}{\var(x)} .
\end{equation}
The population is \emph{nondegenerate at $z$} when this is strictly positive, i.e.\ when
$z$ is not an affine function of $x$.
\end{definition}

\begin{definition}[Augmentation increment]
With $\ip{\zt}{\zt}>0$ set
\[
  \mathrm{pgain} = \frac{\ip{r}{\zt}^2}{\ip{\zt}{\zt}}, \qquad
  \Delta R^2 = \frac{\mathrm{pgain}}{\var(y)} .
\]
\end{definition}

\begin{lemma}[Five-moment form]\label{lem:moment}
Under the standing hypotheses,
\begin{equation}\label{eq:moment}
  \Delta R^2 =
  \frac{\Big(\cov(z,y)-\dfrac{\cov(x,z)\cov(x,y)}{\var(x)}\Big)^2}
       {\Big(\var(z)-\dfrac{\cov(x,z)^2}{\var(x)}\Big)\var(y)} .
\end{equation}
\end{lemma}

\begin{proof}[Proof sketch]
Expand $\ip{r}{\zt}$ using $r=(y-\mu(y))-b(x-\mu(x))$ and the orthogonality defining
$\zt$; the cross terms give exactly $\cov(z,y)-\cov(x,z)\cov(x,y)/\var(x)$. Combine with
\eqref{eq:energy}.
\end{proof}

\begin{definition}[Dashboard; sign-blind predictor]
The \emph{dashboard} relative to $(x,z,y)$ is the triple $(a,c,e)$ as above. A
\emph{sign-blind predictor} is $F:\R^3\to\R$ with $\Delta R^2 = F(a,c,e)$ for every
finite population and admissible configuration.
\end{definition}

\section{The exact invariant content}

\begin{theorem}[Collinearity reading is strictly sub-unit]\label{thm:e1}
If $\var(x),\var(z)>0$ and the partialled energy \eqref{eq:energy} is positive, then
$R^2(x,z)<1$.
\end{theorem}

\begin{proof}
Multiplying the positive partialled energy by $\var(x)>0$ gives
$\var(x)\var(z)-\cov(x,z)^2>0$, which is $R^2(x,z)<1$ after dividing by the positive
product of variances.
\end{proof}

Hence all denominators $1-e$ below are strictly positive.

\begin{theorem}[Partial-correlation form]\label{thm:pcorr}
Under the standing hypotheses,
\begin{equation}\label{eq:pcorr}
  \Delta R^2 = \frac{(\rho_{zy}-\rho_{xy}\rho_{xz})^2}{1-\rho_{xz}^2}.
\end{equation}
In particular $\Delta R^2$ is a function of the three signed correlations alone, and is
invariant under rescaling of $x$, $y$ or $z$.
\end{theorem}

\begin{proof}[Proof sketch]
Write $s_x=\sqrt{\var(x)}$, $s_y$, $s_z$ similarly, and substitute
$\cov(x,y)=\rho_{xy}s_xs_y$ and its analogues into \eqref{eq:moment}. Numerator and
denominator each carry a factor $s_x^2s_y^2s_z^2$; cancelling it (legitimate since the
partialled energy is nonzero) yields \eqref{eq:pcorr}.
\end{proof}

\begin{definition}[Correlation triple product]
$P = \rho_{xy}\,\rho_{xz}\,\rho_{zy}$.
\end{definition}

\begin{theorem}[Dashboard form]\label{thm:dash}
$\displaystyle \Delta R^2 = \frac{c+ae-2P}{1-e}$.
\end{theorem}

\begin{proof}
Expand the numerator of \eqref{eq:pcorr}:
$\rho_{zy}^2-2\rho_{xy}\rho_{xz}\rho_{zy}+\rho_{xy}^2\rho_{xz}^2 = c-2P+ae$, and
$1-\rho_{xz}^2 = 1-e$ by Proposition~\ref{prop:sq}.
\end{proof}

\begin{theorem}[The dashboard pins $|P|$]\label{thm:Psq}
$P^2 = a\,c\,e$.
\end{theorem}

\begin{proof}
$P^2=\rho_{xy}^2\rho_{xz}^2\rho_{zy}^2=R^2(x,y)R^2(x,z)R^2(z,y)$.
\end{proof}

\begin{corollary}[One bit suffices]\label{cor:onebit}
If two populations, possibly on different key sets with different weights, agree on the
three readings and satisfy $PP'\ge0$, then they report the same increment.
\end{corollary}

\begin{proof}
$P^2=ace=a'c'e'=P'^2$ forces $P=\pm P'$; the negative branch together with $PP'\ge0$
forces $P=P'=0$. Apply Theorem~\ref{thm:dash} twice.
\end{proof}

\section{Impossibility and its robustness}

\subsection{The four-key stage}
Fix four keys with uniform weight $1/4$ and take
\[
  x=(1,2,3,4)\ \ (\text{footprint}), \qquad z=(1,1,0,0)\ \ (\text{feature}).
\]
Then $\var(x)=5/4$, $\var(z)=1/4$, $\cov(x,z)=-1/2$, so $R^2(x,z)=4/5$ and
\[
  \zt = \big(-\tfrac1{10},\tfrac3{10},-\tfrac3{10},\tfrac1{10}\big), \qquad
  \ip{\zt}{\zt}=\tfrac1{20}.
\]
The centred features orthogonal to $x$ form a plane; besides $\zt$ it contains
$\varepsilon=(1,-1,-1,1)$, which is centred, orthogonal to $x$, and orthogonal to $\zt$.
Thus $\{\zt,\varepsilon\}$ is an orthogonal basis of the residual plane.

\begin{definition}[The witness family]\label{def:family}
For $b\in\R$ and $u>0$ define targets
\[
  y_B(b,u) = b\,x + \Big(u+\tfrac{5b^2}{u}\Big)\varepsilon, \qquad
  y_C(b,u) = b\,x + \Big(u-\tfrac{5b^2}{u}\Big)\varepsilon + 20b\,\zt .
\]
\end{definition}

\begin{theorem}[Dashboard-identical with flipped sign]\label{thm:famid}
For all $b$ and all $u\neq0$:
\begin{enumerate}
\item $\var(y_B)=\var(y_C)=\dfrac{5b^2u^2+4(u^2+5b^2)^2}{4u^2}$;
\item $\cov(x,y_B)=\cov(x,y_C)=\tfrac54 b$;
\item $\cov(z,y_B)=-\tfrac b2 = -\cov(z,y_C)$;
\item consequently $R^2(x,y_B)=R^2(x,y_C)$ and $R^2(z,y_B)=R^2(z,y_C)$, while the signed
      feature covariances are exact negatives.
\end{enumerate}
\end{theorem}

\begin{proof}[Proof sketch]
All items are four-term evaluations using $\ip{\varepsilon}{\varepsilon}=1$,
$\ip{\varepsilon}{\zt}=0$, $\ip{\zt}{\zt}=1/20$, $\cov(z,\varepsilon)=0$,
$\cov(x,z)=-1/2$ and $\cov(z,\zt)=\ip{\zt}{\zt}=1/20$. For instance
$\cov(z,y_B)=b\cov(x,z)=-b/2$ while $\cov(z,y_C)=-b/2+20b\cdot\frac1{20}=+b/2$. The
$\pm5b^2/u$ shift is calibrated so that the extra energy $(20b)^2/20=20b^2$ carried
along $\zt$ is offset exactly, since
$(u+5b^2/u)^2-(u-5b^2/u)^2=20b^2$.
\end{proof}

\begin{theorem}[Divergent increments]\label{thm:famincr}
For $u>0$,
\begin{equation}\label{eq:famincr}
  \Delta R^2(y_B)=0, \qquad
  \Delta R^2(y_C)=\frac{80\,b^2u^2}{5b^2u^2+4(u^2+5b^2)^2}.
\end{equation}
\end{theorem}

\begin{proof}[Proof sketch]
$\ip{r_B}{\zt}=0$ because $r_B$ is a multiple of $\varepsilon\perp\zt$. For $y_C$,
$\ip{r_C}{\zt}=20b\ip{\zt}{\zt}=b$, so the partial gain is $b^2/(1/20)=20b^2$; divide by
the variance of Theorem~\ref{thm:famid}(1).
\end{proof}

At $(b,u)=(1/10,1/2)$ the targets are
\[
  y_B=(0.7,-0.4,-0.3,1.0), \qquad y_C=(0.3,0.4,-0.7,1.0),
\]
with common variance $149/400$, readings $a=5/149$, $c=4/149$, $e=4/5$, and increments
$0$ and $80/149\approx0.5369$.

\begin{theorem}[Inadmissibility of sign-blind reporting]\label{thm:imposs}
There is no function $F:\R^3\to\R$ with
$\Delta R^2 = F\big(R^2(x,y),R^2(z,y),R^2(x,z)\big)$ for every finite population and
admissible configuration with $\var(x),\var(y),\var(z),\ip{\zt}{\zt}>0$. The statement
already fails on populations supported on four keys.
\end{theorem}

\begin{proof}
Apply $F$ to $y_B$ and $y_C$ at $(b,u)=(1/10,1/2)$. By Theorem~\ref{thm:famid} the
arguments coincide; by Theorem~\ref{thm:famincr} the required values are $0$ and
$80/149$.
\end{proof}

\begin{theorem}[Uniform gap on a box]\label{thm:gap}
If $|b-1/10|<1/100$ and $|u-1/2|<1/100$ then
$\Delta R^2(y_C)-\Delta R^2(y_B)\ge 1/3$.
\end{theorem}

\begin{proof}[Proof sketch]
By \eqref{eq:famincr} the claim reduces to $240b^2u^2\ge 5b^2u^2+4(u^2+5b^2)^2$ on the
box. There $u^2+5b^2<0.3206$, so the right side is below $0.4126$, while
$b^2u^2>(0.09)^2(0.49)^2$ makes the left side exceed $0.4667$.
\end{proof}

\begin{theorem}[An open set of counterexamples]\label{thm:open}
There is an open $V\subseteq\R^2$ containing $(1/10,1/2)$ --- the ball of radius
$1/100$ --- such that for every $(b,u)\in V$ both members of the pair are legitimate
populations with positive target variance, their three readings agree exactly, their
signed feature covariances are exact negatives, the suppressed member has increment
exactly $0$, and the active member has increment at least $1/3$.
\end{theorem}

\begin{theorem}[The ball is spread in moment space]\label{thm:nonconst}
The readings are not constant on $V$: the footprint reading
$R^2(x,y_B)=5b^2u^2/\big(5b^2u^2+4(u^2+5b^2)^2\big)$ takes different values at different
points of $V$. Hence the set of \emph{readings} at which sign-blind prediction fails has
nonempty interior.
\end{theorem}

\section{Rigidity: a two-point ambiguity}

\begin{theorem}[Ambiguity dichotomy]\label{thm:dicho}
Let two finite populations, possibly with different key sets and weights, satisfy the
standing hypotheses and agree on all three readings. Then either
$\Delta R^2 = \Delta R'^2$, or
\[
  \big|\Delta R^2-\Delta R'^2\big| \;=\; A \;:=\; \frac{4\sqrt{a\,c\,e}}{1-e}.
\]
No intermediate value is possible.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:Psq}, $P'^2 = P^2$, so $P'=P$ or $P'=-P$. In the first case
Theorem~\ref{thm:dash} gives equality. In the second, subtracting the two instances of
Theorem~\ref{thm:dash} gives $-4P/(1-e)$, and $|P|=\sqrt{ace}$ while $1-e>0$ by
Theorem~\ref{thm:e1}.
\end{proof}

\begin{theorem}[Admissibility criterion]\label{thm:vanish}
$A=0$ if and only if at least one of $a,c,e$ vanishes.
\end{theorem}

\begin{proof}
$1-e>0$, so $A=0$ iff $ace=0$, iff one nonnegative factor vanishes.
\end{proof}

Since $\{ace=0\}$ is a union of three coordinate planes, sign-blind reporting is
harmless only on a nowhere-dense set of readings. At the base point,
$\sqrt{ace}=4/149$ and $A=(16/149)/(1/5)=80/149$, exactly the observed gap.

\section{How much can be concealed?}

\begin{theorem}[Family ceiling]\label{thm:1617}
For all $b\in\R$ and $u>0$,
\[
  \Delta R^2(y_C)-\Delta R^2(y_B)=\frac{80b^2u^2}{5b^2u^2+4(u^2+5b^2)^2}\;\le\;\frac{16}{17}.
\]
\end{theorem}

\begin{proof}
Clearing the positive denominator, the claim is
$1360b^2u^2 \le 80b^2u^2+64(u^2+5b^2)^2$, i.e.\
$64\big((u^2+5b^2)^2-20b^2u^2\big)\ge0$, and
$(u^2+5b^2)^2-20b^2u^2=(u^2-5b^2)^2\ge0$.
\end{proof}

\begin{theorem}[Attainment]\label{thm:attain}
At $b=1$, $u=\sqrt5$ the two members agree on every reading and
\[
  \Delta R^2(y_C)-\Delta R^2(y_B)=\frac{400}{425}=\frac{16}{17}.
\]
Hence $16/17$ is the greatest concealable share realised by the family, attained on the
ray $u=\sqrt5\,b$, the vanishing locus of the perfect square above.
\end{theorem}

Two four-key populations therefore exist which present identical sign-blind readings
while one attributes $16/17\approx94.1\%$ of its target's variance to the new feature
and the other attributes exactly nothing.

\begin{theorem}[No model explains more than everything]\label{thm:total}
Under the standing hypotheses with $\ip{r}{r}>0$, $R^2(x,y)+\Delta R^2 \le 1$.
\end{theorem}

\begin{proof}
Since $r$ is centred and orthogonal to $x$, the decomposition $y=a+bx+r$ is orthogonal,
so $\var(y)=b^2\var(x)+\ip{r}{r}$ and $R^2(x,y)=b^2\var(x)/\var(y)$. Cauchy--Schwarz
gives $\ip{r}{\zt}^2\le\ip{r}{r}\ip{\zt}{\zt}$, whence
$\Delta R^2\le\ip{r}{r}/\var(y)$. Add.
\end{proof}

\begin{theorem}[Gram inequality in dashboard coordinates]\label{thm:gram}
Under the same hypotheses, $1-a-e-c+2P\ge0$.
\end{theorem}

\begin{proof}
Substituting Theorem~\ref{thm:dash} into Theorem~\ref{thm:total} gives
$(c+ae-2P)/(1-e)\le 1-a$; multiplying by $1-e>0$ and rearranging yields the claim.
\end{proof}

This is the nonnegativity of $\det$ of the $3\times3$ correlation matrix of $(x,y,z)$,
namely $1-\rho_{xy}^2-\rho_{xz}^2-\rho_{zy}^2+2\rho_{xy}\rho_{xz}\rho_{zy}$; note that
it is \emph{derived} here rather than assumed.

\begin{theorem}[Algebraic amplitude ceiling]\label{thm:algceil}
Let $a,c\ge0$ and $0\le e<1$ satisfy $2\sqrt{aec}\le 1-a-e-c$. Then
\[
  \frac{4\sqrt{aec}}{1-e} \;\le\; \frac{2\sqrt e}{1+\sqrt e}.
\]
\end{theorem}

\begin{proof}
Put $\alpha=\sqrt a$, $\gamma=\sqrt c$, $\eta=\sqrt e\in[0,1)$, so
$\sqrt{aec}=\alpha\gamma\eta$ and the hypothesis reads
$2\alpha\gamma\eta\le1-\alpha^2-\eta^2-\gamma^2$. By AM--GM,
$2\alpha\gamma\le\alpha^2+\gamma^2$, hence
\[
  2\alpha\gamma(1+\eta) \le (\alpha^2+\gamma^2)+\big(1-\alpha^2-\gamma^2-\eta^2\big)
  = 1-\eta^2 = 1-e .
\]
Multiply by $2\eta\ge0$ and divide by $(1-e)(1+\eta)>0$.
\end{proof}

\begin{theorem}[Ceiling is below one]\label{thm:ceillt1}
For $0\le e<1$, $\ \dfrac{2\sqrt e}{1+\sqrt e}<1$.
\end{theorem}

\begin{proof}
$\sqrt e<1$ gives $2\sqrt e<1+\sqrt e$.
\end{proof}

\begin{theorem}[Universal ceiling]\label{thm:univ}
Let two finite populations satisfy the standing hypotheses, agree on all three readings,
and have opposite triple products, $P'=-P$. Then
\[
  \big|\Delta R^2-\Delta R'^2\big| \;\le\; \frac{2\sqrt e}{1+\sqrt e} \;<\; 1,
  \qquad e=R^2(x,z).
\]
\end{theorem}

\begin{proof}
Both satisfy Theorem~\ref{thm:gram}; with equal readings and opposite $P$ this reads
$1-a-e-c\pm2P\ge0$, so $2|P|\le1-a-e-c$. Since $|P|=\sqrt{ace}$,
Theorem~\ref{thm:algceil} applies, and by Theorem~\ref{thm:dicho} the left-hand side is
either $0$ or $4\sqrt{ace}/(1-e)$. Theorem~\ref{thm:ceillt1} gives strictness.
\end{proof}

\begin{corollary}[The family sits just below the ceiling]
The four-key family has $e=4/5$, ceiling $2\sqrt{4/5}/(1+\sqrt{4/5})=4/(2+\sqrt5)
\approx0.94427$, and peak concealable share $16/17\approx0.94118$. Thus
$16/17<4/(2+\sqrt5)$, the construction realising $99.7\%$ of the theoretical maximum at
its collinearity level.
\end{corollary}

\section{The repair: exactly one bit}

\begin{theorem}[Unit invariance]\label{thm:units}
For nonzero $\lambda$: replacing $z$ by $\lambda z$ replaces $\zt$ by $\lambda\zt$ and
leaves the partial gain unchanged; replacing $y$ by $\lambda y$ multiplies its residual
by $\lambda$ and its variance by $\lambda^2$, leaving $\Delta R^2$ unchanged.
\end{theorem}

\begin{proof}
$\ip{r}{\lambda\zt}^2/\ip{\lambda\zt}{\lambda\zt}
=\lambda^2\ip{r}{\zt}^2/(\lambda^2\ip{\zt}{\zt})$, and the same cancellation applies to
the numerator against $\var(y)$.
\end{proof}

Thus $\Delta R^2$ is a function on the quotient of moment space by the reparametrisation
group $(\R^\times)^3$, on which the three signed correlations are coordinates. The sign
group $\{\pm1\}^3$ acts on these coordinates; the invariants of the full action are the
three readings, while $\Delta R^2$ is invariant only under the \emph{even} subgroup. The
quotient of the full group by the even subgroup is $\mathbb{Z}/2$, detected by the sign
of $P$: this is the structural reason the loss is one bit and not three.

\begin{definition}[Sign bit and repaired dial]
Put $s=+1$ if $P\ge0$ and $s=-1$ otherwise, and
\[
  G(a,c,e,s) = \frac{c+ae-2s\sqrt{aec}}{1-e}.
\]
\end{definition}

\begin{theorem}[Correctness of the repaired dashboard]\label{thm:repair}
Under the standing hypotheses,
$\Delta R^2 = G\big(R^2(x,y),R^2(z,y),R^2(x,z),s\big)$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:Psq}, $\sqrt{ace}=|P|$ and $s|P|=P$; substitute into
Theorem~\ref{thm:dash}.
\end{proof}

\begin{corollary}[One bit is necessary and sufficient]
There exists $G:\R^4\to\R$ with $\Delta R^2 = G(a,c,e,s)$ on every finite population,
whereas by Theorem~\ref{thm:imposs} no function of $(a,c,e)$ alone suffices. The
inadmissibility of sign-blind reporting is therefore exactly one bit deep.
\end{corollary}

On the base pair both members feed $G$ the arguments $a=5/149$, $c=4/149$, $e=4/5$ with
$\sqrt{ace}=4/149$. The suppressed target has $\rho_{xy}>0$, $\rho_{xz}<0$,
$\rho_{zy}<0$, hence $s=+1$ and $G=0$; the active target has $\rho_{zy}>0$, hence
$s=-1$ and $G=80/149$. Both are correct.

\section{Algorithms and applications}

\begin{algo}[Ambiguity-annotated augmentation report]
\emph{Input:} weights $p$, features $x,z$, target $y$.
\begin{enumerate}
\item Compute the six second moments and the readings $a,c,e$.
\item If $e=1$, report \emph{degenerate}: the feature is an affine function of the
      footprint.
\item Compute $|P|=\sqrt{ace}$ and the amplitude $A = 4|P|/(1-e)$.
\item Compute the signed correlations and $s=\sign(\rho_{xy}\rho_{xz}\rho_{zy})$.
\item Report $\Delta R^2 = (c+ae-2s|P|)/(1-e)$, the amplitude $A$, the alternative value
      $(c+ae+2s|P|)/(1-e)$ that a sign-blind reader could not exclude, and the ceiling
      $2\sqrt e/(1+\sqrt e)$.
\end{enumerate}
Each step is $O(n)$ for $n$ keys plus $O(1)$ arithmetic, so the annotation is free
relative to computing the readings.
\end{algo}

Given only a legacy dashboard $(a,c,e)$ one computes $A$ and the two admissible values
$t_\pm = (c+ae\mp2\sqrt{ace})/(1-e)$. If $A$ is below the decision threshold the legacy
report is \emph{certified}; otherwise it is \emph{indeterminate} and the signs must be
retrieved. By Theorem~\ref{thm:vanish}, certification requires a numerically negligible
reading, so it is the exception rather than the rule.

The construction of Definition~\ref{def:family} generates dashboard-identical pairs with
any prescribed gap in $(0,16/17]$, which is useful both for stress-testing analytics
pipelines and pedagogically: the $\varepsilon/\zt$ decomposition of the residual plane
shows the collapse is a two-dimensional geometry problem, not a high-dimensional
artefact.

Practical consequences include: screening rules of the form ``drop candidates with
$R^2(z,y)<\tau$ and $R^2(x,z)>\theta$'' are precisely what the family defeats, since the
base pair has $c\approx0.027$, $e=0.8$ and yet one member contributes $54\%$ of the
target variance; secondary analyses working from published squared correlations cannot
recover increments at all, with a two-point uncertainty of known spread; storing one
sign bit per triple is the complete fix; and auditors without sign information can still
quote the worst case $2\sqrt e/(1+\sqrt e)$.

\section{Discussion and future directions}

The four statements --- impossibility, openness, rigidity, repair --- give a complete
description of the information content of a sign-blind report: the map from readings to
increments is not a function; the multivaluedness is not confined to a thin set; the
fibres have cardinality exactly two with explicit separation; and one bit resolves them.
The ceilings measure the worst case inside a concrete family and universally. Worth
stressing is the logical route in Section~6: positive semidefiniteness of the
correlation matrix, usually invoked as structure, is obtained here as a corollary of
``a model cannot explain more than the whole variance'', itself Cauchy--Schwarz applied
to the residual and partialled feature.

\subsection*{Future directions}
\begin{itemize}
\item \textbf{Multi-feature sign cohomology.} For an augmentation by $k$ features at
once, the dashboard analogue is the collection of pairwise variance shares, and the
missing datum should be the set of cycle signs
$\sign(\rho_{i_1i_2}\rho_{i_2i_3}\cdots\rho_{i_mi_1})$ of the correlation graph.
Conjecture: the missing information is exactly $H^1$ of the complete graph on $k+2$
vertices with $\mathbb{Z}/2$ coefficients modulo the vertex-flip action, i.e.\
$\binom{k+1}{2}$ bits, and a spanning tree's worth of signs determines all of them.
\item \textbf{Sharpness of the universal ceiling.} Is $2\sqrt e/(1+\sqrt e)$ attained for
every $e\in(0,1)$, or only approached? The AM--GM step is tight when $a=c$, suggesting an
extremal configuration with equal footprint and feature readings.
\item \textbf{Statistical version.} With sample moments from $n$ draws, how large must
$n$ be before the sign of $P$ is determined with confidence $1-\delta$? Conjecture: the
posterior for $\Delta R^2$ is asymptotically a two-component mixture with weights given
by the sign posterior and separation $A$.
\item \textbf{Which invariants pin the sign?} Are there natural population invariants ---
order statistics, monotonicity constraints, sign patterns of the raw features --- forcing
$P>0$? Any such condition would be a genuinely new constraint on admissible populations,
carving out a class on which sign-blind reporting is admissible after all.
\end{itemize}

